2.2 Exercise 2
Task: Download the first 3 works by Wells, H. G. (Herbert George), create a token table, then build a three-book dataset and compare top words.

wells_works &lt;- gutenberg_works(author == "Wells, H. G. (Herbert George)") |&gt;
  arrange(gutenberg_id) |&gt;
  slice_head(n = 3)

wells_books &lt;- gutenberg_download(wells_works$gutenberg_id, meta_fields = "title")

wells_tokens &lt;- wells_books |&gt;
  unnest_tokens(word, text) |&gt;
  anti_join(stop_words, by = join_by(word))

wells_top &lt;- wells_tokens |&gt;
  count(title, word, sort = TRUE) |&gt;
  group_by(title) |&gt;
  slice_head(n = 12) |&gt;
  ungroup()

wells_top |&gt;
  mutate(word = fct_reorder(word, n)) |&gt;
  ggplot(aes(x = n, y = word, fill = title)) +
  geom_col(show.legend = FALSE) +
  facet_wrap(vars(title), scales = "free_y") +
  labs(
    title = "Top words in Wells' books",
    x = "Count",
    y = NULL
  )








Interpretation note:

gutenberg_works(author == "Wells, H. G. (Herbert George)") returns metadata (including IDs) for that author.
arrange(gutenberg_id) |&gt; slice_head(n = 3) keeps the first three works by Gutenberg ID.
wells_tokens gives a mini-corpus for Wells, and bind_rows() combines it with previously prepared token tables.
Shared high-frequency content words may reflect common literary vocabulary.
Distinctive words often point to characters, setting, or genre themes.

3.2 Exercise 2
Task: Top 25 first English translations and discuss limits.

xml_first_translation &lt;- entry_sample |&gt;
  map(
    \(entry_node) {
      en_translations &lt;- xml_find_all(
        entry_node,
        ".//meaning/targetLanguage[@lang='en']/translation"
      ) |&gt;
        xml_text()

      tibble(
        lemma = node_text_or_na(entry_node, ".//lemma"),
        first_en_translation = en_translations |&gt; first(default = NA_character_)
      )
    }
  ) |&gt;
  list_rbind()

xml_first_translation |&gt;
  filter(!is.na(first_en_translation)) |&gt;
  count(first_en_translation, sort = TRUE) |&gt;
  slice_head(n = 25)

