3.4 Analyze word pairs with bigrams (Jean Paul)
Following the tidytext n-grams workflow, we now move from single words to bigrams (two consecutive words).
Here we use three works by the German author Jean Paul from Project Gutenberg.

jean_paul_works &lt;- gutenberg_works(author == "Jean Paul") |&gt;
  arrange(gutenberg_id) |&gt;
  slice_head(n = 3)

jean_paul_books &lt;- gutenberg_download(
  jean_paul_works$gutenberg_id,
  meta_fields = c("author", "title")
) |&gt;
  filter(
    is.na(lag(text)) | text != lag(text),
    .by = gutenberg_id
  )

jean_paul_bigrams &lt;- jean_paul_books |&gt;
  unnest_tokens(bigram, text, token = "ngrams", n = 2) |&gt;
  separate_wider_delim(
    bigram,
    delim = " ",
    names = c("word1", "word2"),
    too_few = "align_start"
  ) |&gt;
  filter(!is.na(word1), !is.na(word2)) |&gt;
  anti_join(stop_words, by = join_by(word1 == word)) |&gt;
  anti_join(stop_words, by = join_by(word2 == word))

jean_paul_bigram_counts &lt;- jean_paul_bigrams |&gt;
  count(title, word1, word2, sort = TRUE)

jean_paul_bigram_counts |&gt;
  mutate(bigram = str_c(word1, word2, sep = " ")) |&gt;
  group_by(title) |&gt;
  slice_head(n = 10) |&gt;
  ungroup() |&gt;
  select(title, bigram, n)

# A tibble: 30 × 3
   title                                                        bigram         n
   &lt;chr&gt;                                                        &lt;chr&gt;      &lt;int&gt;
